import 'package:cached_network_image/cached_network_image.dart';import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../providers/providers.dart';
class ProfileScreen extends ConsumerWidget{const ProfileScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final user=ref.watch(authProvider).user;if(user==null)return const SizedBox();return Scaffold(appBar:AppBar(title:const Text('Profil')),body:ListView(padding:const EdgeInsets.all(16),children:[Center(child:Column(children:[CircleAvatar(radius:45,backgroundImage:user.avatarUrl!=null?CachedNetworkImageProvider(user.avatarUrl!):null,child:user.avatarUrl==null?Text(user.name[0],style:const TextStyle(fontSize:30,fontWeight:FontWeight.bold)):null),const SizedBox(height:12),Text(user.name,style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text(user.email??user.phone??'',style:const TextStyle(color:Colors.grey))])),const SizedBox(height:28),_Tile(Icons.favorite_outline,'Sevimlilar','Sevimli kino va telekanallar',()=>context.push('/favorites')),_Tile(Icons.history_rounded,'Ko‘rish tarixi','Ko‘rishni davom ettirish',()=>context.push('/history')),_Tile(Icons.settings_outlined,'Sozlamalar','Rejim, sifat va bildirishnomalar',()=>context.push('/settings')),const SizedBox(height:10),ListTile(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14)),tileColor:Colors.red.withValues(alpha:.08),leading:const Icon(Icons.logout,color:Colors.redAccent),title:const Text('Chiqish',style:TextStyle(color:Colors.redAccent,fontWeight:FontWeight.w600)),onTap:()=>showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Hisobdan chiqish'),content:const Text('Hisobdan chiqishni tasdiqlaysizmi?'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Yo‘q')),FilledButton(onPressed:(){Navigator.pop(c);ref.read(authProvider.notifier).logout();},child:const Text('Ha, chiqish'))]))) ]));}}
class _Tile extends StatelessWidget{final IconData icon;final String title,subtitle;final VoidCallback tap;const _Tile(this.icon,this.title,this.subtitle,this.tap);@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.only(bottom:9),child:ListTile(shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14)),tileColor:Theme.of(context).colorScheme.surface,leading:Icon(icon,color:Theme.of(context).colorScheme.primary),title:Text(title,style:const TextStyle(fontWeight:FontWeight.w600)),subtitle:Text(subtitle,style:const TextStyle(fontSize:11)),trailing:const Icon(Icons.chevron_right),onTap:tap));}
